  console.log('render', item.id)
  return <li onClick={() => onSelect(item.id)}>{item.name}</li>
})

function ProductList({ items, query }) {
  // 每次渲染都重算
  const visible = items
    .filter((i) => i.name.includes(query))
    .sort((a, b) => a.price - b.price)

  return (
    <ul>
      {visible.map((item) => (
        <ProductRow
          key={item.id}
          item={item}
          // 每次渲染都是新函数，memo 失效
          onSelect={() => addToCart(item.id)}
        />
      ))}
    </ul>
  )
}
